--> statement-breakpoint
-- Any row the seed does not know keeps its numbers but moves to the new stat keys.
UPDATE public.equipment_catalog SET "affixes" = (
  SELECT COALESCE(jsonb_agg(jsonb_set(a, '{stat}', to_jsonb(CASE a->>'stat'
    WHEN 'defense' THEN 'shellHardness'
    WHEN 'attack' THEN 'pincerTorque'
    WHEN 'intelligence' THEN 'neuralLatency'
    WHEN 'speed' THEN 'ecdysisDiscipline'
    WHEN 'perception' THEN 'depthTolerance'
    ELSE a->>'stat' END))), '[]'::jsonb)
  FROM jsonb_array_elements("affixes") AS a
)
WHERE "affixes"::text ~ '"stat": ?"(defense|attack|intelligence|speed|perception)"';
